tests/ci_pipeline.test.mjs_add_shell_syn.add:
describe('every run: block is shell-safe', () => {
  it('bash -n parses every extracted step', () => {
    for (const [file, doc] of [['ship.yml', ship], ['nightly.yml', nightly]]) {
      for (const [jobName, job] of Object.entries(doc.jobs)) {
        for (const step of job.steps ?? []) {
          if (!step.run) continue;
          const r = spawnSync('bash', ['-n'], { input: step.run, encoding: 'utf8' });
          assert.equal(r.status, 0, `${file}/${jobName}: ${step.name || step.uses}: ${r.stderr}`);
        }
      }
    }
  });
  it('never wraps a `node -e` in double quotes when its body uses template literals', () => {
    // ${...} inside a double-quoted bash string is expanded by bash before node runs.
    const rx = /node\s+-e\s+"[^"]*\$\{[^}]+\.[^}]+\}/;
    assert.ok(!rx.test(shipText), 'use `node - <<\'NODE\'` heredoc for template literals');
    assert.ok(!rx.test(nightlyText));
  });
});

